fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var sum = 0;
    var number = 1;
    while number <= 40 {
        sum += number;
        number += 1;
    }

    var product = 1;
    number = 1;
    while number <= 8 {
        product = product * number;
        number += 1;
    }

    io.write(text: sum.to_text().concat(other: " ").concat(other: product.to_text()))?;
    return Ok(unit);
}

fn sum_to(n: Int) -> Int {
    var current = 1;
    var total = 0;
    while current <= n {
        total = total + current;
        current = current + 1;
    }
    total
}

fn line(n: Int) -> String {
    n.to_text()
        .concat(other: ": ")
        .concat(other: sum_to(n).to_text())
        .concat(other: "\n")
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    io.write(text: line(12))?;
    io.write(text: line(30))?;
    io.write(text: line(7))?;
    return Ok(unit);
}
